###### HYPERSCALING METHOD ######
L <- getTSD_ecdf(abs(X), t=1, n=1000, eta=1, domain=exp.domain)
Ly <- diff(L$y)/diff(L$x)
Lx <- L$x[-1,]

xi <- 1.6/2
zeta <- 1
alpha <- 3
beta <- alpha * (zeta - xi)
t <- ttg
{
    # Bulk
    Qx <- sweep(Lx, 2, t^xi, '/')
    Qy <- sweep(Ly, 2, t^xi, '*')

    mplot((Qx), (Qy), type='s', log='xy', 
	  xlab=tex("\\Delta x / t^\\xi -- \\Delta x / t^{\\xi+\\zeta} "),
	  ylab=tex("t^\\xi P(\\Delta x, t) -- t^{\\xi+\\zeta} P(\\Delta x, t)"),
	  xlim=c(1e-3, 100), ylim=c(1e-6, 1e9))

    # Tails
    Qx <- sweep(Lx, 2, t^zeta, '/')
    Qy <- sweep(Ly, 2, t^(zeta + beta), '*')
    mplot((Qx), (Qy), type='s', add=TRUE)
    curve(from=1e-4, to=1000, expr=0.15*x^(-4), lwd=2, lty='dashed', add=TRUE)
}



